import {SHOP} from './economy.js';
export function createShopUI({profile,view,modal,closeModal,sync,preview,restorePreview}){
 const $=id=>document.getElementById(id);
 let busy=false;
 const locked=async fn=>{if(busy)return;busy=true;try{return await (navigator.locks?navigator.locks.request('bean-dash-wallet',fn):fn());}finally{busy=false;}};
 const shop=()=>{
  const p=profile.get();
  modal(`<span class="pill">RUNNER EXCHANGE · <b>${p.coins}</b> COINS</span><h2>Make every coin count.</h2><p>Earn coins on the course. No real-money purchases. Power-ups and revivals are solo only.</p><div class="shop-grid">${SHOP.map(i=>`<article class="shop-item"><small>${i.kind.toUpperCase()}</small><h3>${i.name}</h3><p>${i.description}</p><b>${i.price} coins</b>${i.kind==='power'?`<span> · In bag: ${p.inventory[i.id]||0}</span>`:''}<button data-buy="${i.id}" ${p.owned.includes(i.id)||p.coins<i.price?'disabled':''}>${p.owned.includes(i.id)?'Owned':p.coins<i.price?'Need '+(i.price-p.coins)+' more':'Buy'}</button>${!['power','chest'].includes(i.kind)?`<button data-preview="${i.id}">3D preview</button>`:''}${p.owned.includes(i.id)?`<button data-equip="${i.id}">${p.equipped[i.kind]===i.id?'Unequip':'Equip'}</button>`:''}</article>`).join('')}</div><p>Chest odds: shield, sprint, double jump and magnet — 25% each. Duplicate consumables stack up to 99. Tour earnings: up to 500 coins per run. Endurance's cap scales with distance (100 coins per km, minimum 500), including finish bonuses. Revivals in Endurance cost 100, 125, 150… up to 250 coins.</p><button id="shop-done" class="primary-button">BACK TO LOBBY</button>`,{wide:true});
  document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>confirm(SHOP.find(i=>i.id===b.dataset.buy)));
  document.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>locked(()=>{profile.equip(b.dataset.equip);const i=SHOP.find(i=>i.id===b.dataset.equip);if(i.appearance&&profile.get().equipped.look===i.id)profile.update({appearance:{...profile.get().appearance,...i.appearance}});sync();shop();}));
  document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{const i=SHOP.find(i=>i.id===b.dataset.preview);preview(i);modal(`<span class="pill">LIVE 3D PREVIEW</span><h2>${i.name}</h2><p>${i.description}</p><p>Drag outside this panel to rotate. Scroll to zoom. C resets the camera.</p><button id="preview-back" class="primary-button">BACK TO SHOP</button>`);document.body.classList.add('customizer-open');$('modal').classList.add('customizer');view.customizing=true;$('preview-back').onclick=()=>{restorePreview();shop();};});
  $('shop-done').onclick=()=>{restorePreview();closeModal();};
 };
 function confirm(item){const token=crypto.randomUUID();modal(`<span class="pill">CONFIRM PURCHASE</span><h2>${item.name}</h2><p>${item.description}</p><div class="purchase-price">${item.price} <small>coins</small></div><p>Balance: ${profile.get().coins} coins</p><button id="purchase-confirm" class="primary-button">BUY FOR ${item.price} COINS</button><button id="purchase-cancel" class="secondary-button">Cancel</button>`);$('purchase-cancel').onclick=shop;$('purchase-confirm').onclick=()=>locked(()=>{const result=profile.purchase(item.id,token);sync();modal(`<span class="pill">${result.ok?'PURCHASE COMPLETE':'PURCHASE NOT COMPLETED'}</span><h2>${result.ok?SHOP.find(i=>i.id===result.reward)?.name||item.name:result.reason}</h2><p class="coin-deduction">${result.ok?'−'+result.cost+' coins':''}</p><p>Balance: ${profile.get().coins} coins</p><button id="purchase-done" class="primary-button">BACK TO SHOP</button>`);$('purchase-done').onclick=shop;});}
 return {shop,locked};
}
